async (page) => {
  const check = (condition, message) => { if (!condition) throw new Error(message); };
  const url = 'http://127.0.0.1:4174/';
  const checks = [];
  await page.emulateMedia({ reducedMotion: 'no-preference' });
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.goto(url);
  await page.waitForFunction(() => document.documentElement.classList.contains('rendering'));
  const scroll = async p => {
    await page.evaluate(p => scrollTo(0, innerHeight * 2 * p), p);
    await page.waitForFunction(p => Math.abs(window.__unravelStudy().progress - p) < .015, p);
  };
  await scroll(0);
  await scroll(.7);
  check(await page.locator('h1').evaluate(el => getComputedStyle(el).opacity === '0'), 'Heading must wait for the environment');
  await scroll(.84);
  check(await page.locator('h1').evaluate(el => Number(getComputedStyle(el).opacity) > 0), 'Heading reveal missing');
  check(await page.locator('#hero-actions').evaluate(el => getComputedStyle(el).visibility === 'hidden'), 'CTAs appeared too early');
  await scroll(1);
  await page.getByRole('link', { name: 'See the workflow' }).click();
  await page.waitForFunction(() => document.querySelector('#study').getBoundingClientRect().top < innerHeight);
  await page.waitForTimeout(150);
  const offscreenTime = await page.evaluate(() => window.__unravelStudy().scene.ambientTime);
  await page.waitForTimeout(300);
  check(await page.evaluate(t => window.__unravelStudy().scene.ambientTime === t, offscreenTime), 'Offscreen rendering did not pause');
  checks.push('Environment-first reveal, staggered controls and local CTA');
  await scroll(0);
  await page.getByRole('button', { name: 'Skip Intro' }).focus();
  await page.keyboard.press('Enter');
  await page.waitForFunction(() => window.__unravelStudy().progress === 1);
  check(await page.locator('h1').evaluate(el => document.activeElement === el), 'Skip must focus the hero');
  checks.push('Keyboard skip bypasses intro and focuses heading');
  const ambientBefore = await page.evaluate(() => window.__unravelStudy().scene);
  await page.waitForTimeout(700);
  const ambientAfter = await page.evaluate(() => window.__unravelStudy().scene);
  check(ambientAfter.ambientTime > ambientBefore.ambientTime, 'Idle environment did not animate');
  check(JSON.stringify(ambientAfter.camera) === JSON.stringify(ambientBefore.camera), 'Idle camera moved');
  await page.getByRole('button', { name: 'Pause motion' }).click();
  const frozen = await page.evaluate(() => window.__unravelStudy().scene.ambientTime);
  await page.waitForTimeout(350);
  check(await page.evaluate(t => window.__unravelStudy().scene.ambientTime === t, frozen), 'Pause failed');
  await scroll(.4);
  check(await page.locator('h1').evaluate(el => getComputedStyle(el).visibility === 'hidden'), 'Reverse scrolling failed');
  await page.getByRole('button', { name: 'Resume motion' }).click();
  for (const p of [.9, .1, 1, 0, .7, 1]) await scroll(p);
  checks.push('Ambient motion with stationary camera, pause, reverse and rapid scrolling');
  await page.setViewportSize({ width: 390, height: 844 });
  await page.reload();
  await page.waitForFunction(() => document.documentElement.classList.contains('rendering'));
  await scroll(1);
  check(await page.evaluate(() => window.__unravelStudy().scene.quality === 'mobile'), 'Mobile quality missing');
  check(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth), 'Mobile horizontal overflow');
  checks.push('Mobile framing/quality and no horizontal overflow');
  await page.emulateMedia({ reducedMotion: 'reduce' });
  await page.waitForFunction(() => window.__unravelStudy().reduced && window.__unravelStudy().fallback);
  check(await page.locator('h1').isVisible(), 'Reduced-motion hero missing');
  check(await page.locator('#journey').evaluate(el => el.getBoundingClientRect().height <= innerHeight + 1), 'Reduced-motion intro space remains');
  await page.emulateMedia({ reducedMotion: 'no-preference' });
  await page.waitForFunction(() => document.documentElement.classList.contains('rendering'));
  checks.push('Live reduced-motion preference change and restoration');
  await page.evaluate(() => {
    const gl = document.querySelector('canvas').getContext('webgl2');
    gl.getExtension('WEBGL_lose_context').loseContext();
  });
  await page.waitForFunction(() => window.__unravelStudy().fallback);
  check(await page.locator('h1').isVisible(), 'Context-loss fallback missing');
  checks.push('Context-loss fallback preserves hero and controls');
  const browser = page.context().browser();
  const unavailable = await browser.newContext();
  await unavailable.addInitScript(() => {
    const getContext = HTMLCanvasElement.prototype.getContext;
    HTMLCanvasElement.prototype.getContext = function(type, ...args) {
      return type === 'webgl2' || type === 'webgl' ? null : getContext.call(this, type, ...args);
    };
  });
  const fallbackPage = await unavailable.newPage();
  await fallbackPage.goto(url);
  await fallbackPage.waitForFunction(() => window.__unravelStudy()?.fallback);
  check(await fallbackPage.locator('h1').isVisible(), 'Unsupported WebGL fallback missing');
  await unavailable.close();
  const failedChunk = await browser.newContext();
  await failedChunk.route('**/src/scene.ts*', route => route.abort());
  const failedPage = await failedChunk.newPage();
  await failedPage.goto(url);
  await failedPage.waitForFunction(() => window.__unravelStudy()?.fallback);
  check(await failedPage.locator('h1').isVisible(), 'Renderer loading failure fallback missing');
  await failedChunk.close();
  checks.push('Unavailable WebGL and failed renderer-chunk fallback');
  for (const filename of ['atrium.glb', 'indirect-light.png']) {
    const missingAsset = await browser.newContext();
    await missingAsset.route(`**/architecture/${filename}`, route => route.abort());
    const missingPage = await missingAsset.newPage();
    await missingPage.goto(url);
    await missingPage.waitForFunction(() => window.__unravelStudy()?.fallback);
    check(await missingPage.locator('h1').isVisible(), `Missing ${filename} must preserve fallback`);
    await missingAsset.close();
  }
  checks.push('Missing GLB and baked-light asset fallbacks');
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.goto(url);
  await page.waitForFunction(() => document.documentElement.classList.contains('rendering'));
  return { passed: checks.length, checks };
}
